#include <stdio.h>
#include <algorithm>
#include <vector>
#include <string.h>
#define m1 998244353
#define m2 1000000007
#define MS 2000010
#define ll long long
using namespace std;
struct Set
{
    int sz[MS],n;ll H;
    void init(vector<ll> ve)
    {
        n=ve.size();H=0;
        for(int i=0;i<n;i++)
        {
            sz[i]=(ve[i]%m1+m1)%m1;
            H+=sz[i];
        }
        sort(sz,sz+n);
    }
    int ask(ll x)
    {
        x=(x%m1+m1)%m1;
        int l=0,r=n;
        while(l<r)
        {
            int m=(l+r)>>1;
            if(x+sz[m]>=m1)r=m;
            else l=m+1;
        }
        ll rt=H+1ll*x*n-1ll*m1*(n-l);
        return (rt%m2+m2)%m2;
    }
}se[15];ll tm,tt,mi[15],su[15];vector<ll> v0;
int sz[15];char zf[15];
void dfs0(int u,int s,int d)
{
    tm+=1;
