    return rt;
}
void dfs3(ll u,int s,int d,int n,int eq)
{
    if(s>n||(s==n&&eq>0))return;
    tt+=1;
    if(d==6)
    {
        ans=(ans+((tt-u)%m1+m1)%m1)%m2;
        tt+=count(u,s,n,eq)-1;return;
    }
    for(int i=0;i<10;i++)
        dfs3(u*10+i,s+1,d+1,n,eq==0?i-sz[s]:eq);
}
void dfs1(int u,int s,int n,int eq)
{
    if(s>n||(s==n&&eq>0))return;
    tm+=1;
